import {PRIORITIES,normalisePriority,normaliseDrive,prioritise,isOverdue,isCarried,workload,focusSeconds,mayPrompt,parseTaskList,minutesLabel,timeInput,readTime} from './productivity.mjs';
import {AREAS,CATALOG,uid,dateKey,shiftDate,dayOfWeek,initialState,validateState,isDone,isScheduled,forToday,earned,balance,completeTask,undoCompletion,build,logStart} from './domain.mjs';
import {worldBackdropHTML,worldPageHTML,modelHTML,mountWorldViews,mountModelPreviews,beginEarnedItem,clearWorldDraft} from './world-view.mjs';
import {createProblemBook} from './problem-ui.mjs';
import {linkForTask} from './problems.mjs';
import {createMeadowOverlay} from './meadow-overlay.mjs';
import {currentSky,skyClockText} from './sky-time.mjs';
import {DEFAULT_SKY_LOCATION,manualSkyLocation,requestSkyLocation} from './sky-location.mjs';
import {cameraAction,previewWaterWave,waterStatus} from './world-renderer.mjs';
import {BACKGROUNDS,normaliseBackground,backgroundRain} from './backgrounds.mjs';
import {trailerAction,refreshTrailerControls,vhsInspectorHTML,vhsFilmHTML} from './video-store-tv.mjs';
const overlay=createMeadowOverlay(document);
let renderedView='',locationRequest=0,locationPending=false;
const KEY='daycraft.v1', app=document.querySelector('#app'), modal=document.querySelector('#modal');
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={problems:'M9 3h10a1 1 0 0 1 1 1v15H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h2ZM9 3v16m3-11h5m-5 4h4M5 17c0 2 1 4 3 4h12',rain:'M7 13H6a4 4 0 1 1 .8-7.9A6 6 0 0 1 18 5a4 4 0 0 1 0 8h-1M8 16l-1 4m6-4-1 4m6-4-1 4',sun:'M12 3v1m0 16v1M3 12h1m16 0h1M5.6 5.6l.7.7m11.4 11.4.7.7M5.6 18.4l.7-.7M17.7 6.3l.7-.7M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',leaf:'M20 3C9 2 3 8 5 15c2 7 15 5 15-12ZM5 20 16 8',tasks:'M9 6h11M9 12h11M9 18h11M3 6l1 1 2-3M3 12l1 1 2-3M3 18l1 1 2-3',world:'m3 9 9-5 9 5-9 5-9-5Zm0 5 9 5 9-5M3 18l9 5 9-5',chart:'M4 3v17h17M8 15v-4m5 4V7m5 8V4',settings:'M9 3h6l1 3 3 1 2 5-2 4-3 1-1 4H9l-1-4-3-1-2-4 2-5 3-1 1-3Zm7 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0',plus:'M12 5v14M5 12h14',arrow:'M4 12h15m-5-5 5 5-5 5',check:'m5 12 4 4L19 6',play:'m8 4 12 8-12 8Z',more:'M5 12h.1M12 12h.1M19 12h.1',close:'M6 6l12 12M6 18 12 6',briefcase:'M3 7h18v13H3ZM8 7V4h8v3M3 12q9 5 18 0M12 12v4',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',flag:'M5 21V4m0 0c6-5 9 5 15 0v10c-6 5-9-5-15 0',block:'M7 3h10l4 4v10l-4 4H7l-4-4V7ZM8 12h8',repeat:'m17 2 4 4-4 4M3 10V6h18M7 22l-4-4 4-4m14 0v4H3',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',heart:'M12 20S2 14 2 8c0-6 8-6 10-1 2-5 10-5 10 1 0 6-10 12-10 12Z',box:'m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 5 9-5M12 12v10M7 5l9 5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',pause:'M8 5v14M16 5v14',back:'M9 5 3 11l6 6m-6-6h12a5 5 0 0 1 0 10',edit:'m4 17 1-5L16 1l5 5L10 17l-6 1Zm9-13 5 5',shield:'M12 2 3 6v6q0 7 9 10 9-3 9-10V6Z',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
let s=initialState(),storageIssue='',view=globalThis.location?.hash==='#world'?'world':globalThis.location?.hash==='#problems'?'problems':'today',taskTab='all',areaFilter='all',query='',pendingImport=null,dialogKind='',toastHandle,lastPromptAt=Date.now(),focusAlerted='',lastPaceAt=0;
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);s=validateState(saved);if(saved.version<3){try{if(!localStorage.getItem(KEY+'.before-productivity'))localStorage.setItem(KEY+'.before-productivity',raw);}catch{}}}}catch{try{const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem(KEY+'.recovery',raw);}catch{}storageIssue='Your saved data could not be loaded. Export the recovery copy in Settings before adding new tasks.';}
const requestedScene=new URLSearchParams(globalThis.location?.search||'').get('scene');if(Object.hasOwn(BACKGROUNDS,requestedScene))s.settings.background=requestedScene;
let day=dateKey(new Date(),s.settings.zone);
function today(){return dateKey(new Date(),s.settings.zone);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(s));storageIssue='';window.dispatchEvent(new Event('daycraft:changed'));return true;}catch{storageIssue='Changes are only in memory: browser storage is unavailable or full. Export a backup from Settings before closing.';return false;}}
function commit(){persist();render();}
function toast(message){const el=document.querySelector('#toast');el.textContent=storageIssue?message+' Changes may not be saved; see Settings for a backup.':message;el.classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>el.classList.remove('show'),4500);}
function btn(text,action,extra='',classes=''){return `<button type="button" class="btn ${classes}" data-action="${action}" ${extra}>${text}</button>`;}
function areaTag(area){return `<span class="area" style="--area:${AREAS[area].color}"><i class="area-dot"></i>${AREAS[area].name}</span>`;}
function dateLabel(d,opts={day:'numeric',month:'short'}){return new Intl.DateTimeFormat('en-AU',{...opts,timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));}
function heading(title,description,right=''){return `<div class="page-heading"><div><p class="eyebrow">${dateLabel(day,{weekday:'long',day:'numeric',month:'long'})}</p><h1>${title}</h1><p>${description}</p></div>${right}</div>`;}

function skyDetails(info){if(s.settings.background==='mall')return 'Mall atrium · A quiet afternoon, circa 1990. The skylight stays bright while the fountain flows.';if(s.settings.background==='stormwatch')return 'Stormwatch · A warm refuge above the sea. The coastal storm has its own light and weather.';if(s.settings.background==='poolrooms')return 'Windowless poolrooms · The cove lights stay on.';if(s.settings.background==='cinema')return 'Soft restaurant lighting · A quiet corner of the 90s.';if(s.settings.background==='video-store')return s.settings.storeLiveTime?'The shop lights stay on. The view outside follows your local time.':'Blue sky outside · Switch to Local time to follow daylight where you are.';if(s.settings.background==='forest')return info.daylight<.4?'Forest dusk · Warm lamplight beside the empty stop':'Daylight through the canopy · The lamp comes on at dusk';if(s.settings.background==='water')return info.daylight<.999?'Cinematic moon · Silver light across the water and tidal wave':'The water-world moon appears after dark.';const moon=info.moon,direction=['N','NE','E','SE','S','SW','W','NW'][Math.round(moon.azimuth/45)%8];return `${moon.name} · ${(moon.fraction*100).toFixed(1)}% illuminated · ${moon.altitude>0?direction+', '+Math.round(moon.altitude)+'° above the horizon':'below the horizon'}`;}
function updateSkyUI(){
 const sky=currentSky(s.settings.skyLocation),clock=document.querySelector('#sky-clock'),details=document.querySelector('#sky-details');
 if(clock)clock.textContent=s.settings.background==='mall'?'A quiet afternoon, circa 1990':s.settings.background==='stormwatch'?'Safe above the storm':s.settings.background==='poolrooms'?'Beyond the Bend':skyClockText(sky);if(details)details.textContent=skyDetails(sky);
 app.classList[sky.daylight<.4&&!['cinema','poolrooms','stormwatch','mall'].includes(s.settings.background)&&(s.settings.background!=='video-store'||s.settings.storeLiveTime)?'add':'remove']('night-sky');
 app.classList[s.settings.background==='water'?'add':'remove']('water-world');
 app.classList[s.settings.background==='stormwatch'?'add':'remove']('stormwatch-world');
 app.classList[s.settings.background==='mall'?'add':'remove']('mall-world');
 app.classList[s.settings.background==='poolrooms'?'add':'remove']('poolrooms-world');
 app.classList[s.settings.background==='cinema'?'add':'remove']('cinema-world');
 app.classList[s.settings.background==='video-store'?'add':'remove']('video-store-world');
 const wave=document.querySelector('#water-status');if(wave&&s.settings.background==='water')wave.textContent=s.settings.calm?'Still water · Calm mode':waterStatus();
}
function chooseBackground(id){const background=normaliseBackground(id);if(s.settings.background===background)return;clearWorldDraft();s.settings.background=background;commit();}
function backgroundSettings(){return `<section class="card padded"><h2>Choose your background</h2><div class="background-options">${Object.entries(BACKGROUNDS).map(([id,b])=>`<button type="button" class="background-option ${s.settings.background===id?'selected':''}" data-action="background" data-background="${id}" aria-pressed="${s.settings.background===id}"><span class="background-swatch ${id}" aria-hidden="true"></span><strong>${b.name}</strong><span>${b.description}</span></button>`).join('')}</div><p class="small-text">Your tasks, problems and progress are shared across backgrounds. Your earned items stay arranged in the meadow; Place or Move opens it for you.</p>${s.settings.background==='mall'?`<div class="water-settings"><h3>A quiet afternoon, circa 1990</h3><p>Side A Records, Rewind Video, The Book Nook and Galaxy Arcade each have their own character. Sit among the palms and watch five frothy fountain jets, falling droplets and spreading ripples. The escalator treads and shop screens move softly in the background.</p><p>Choose a view, then drag to look around from your seat or pinch to zoom. Pause scenery freezes all movement. Space hides the panels.</p>${mallControlsHTML()}</div>`:''}${s.settings.background==='stormwatch'?`<div class="water-settings"><h3>Safe above the storm</h3><p>Watch the surf roll below the cliffs, spray rise over the breakwater and rain run down the closed windows. Clouds drift, distant lightning lights the sea, and the fire and mug steam move quietly inside.</p><p>Choose a view, then drag to look around from your seat or pinch to zoom. The camera stays steady. Pause scenery freezes every layer; it also pauses when you hide the tab. Rain and lightning have their own saved switches.</p>${stormControlsHTML()}</div>`:''}${s.settings.background==='poolrooms'?`<div class="water-settings"><h3>Beyond the Bend</h3><p>Look across the submerged steps, visit the manta spillway, or slip under the low bridge. Drag to look around and pinch or scroll to zoom. Calm mode stills the water.</p>${poolControlsHTML()}</div>`:''}${s.settings.background==='video-store'?`<div class="water-settings"><h3>Welcome to After Hours Video</h3><p>Walnut joinery, burgundy carpet, framed film posters and clear windows over a hedge and car park. Use Play trailers once to begin the four-film reel; sound starts off. It pauses when you hide the tab or leave the store. Trailers need an internet connection.</p><p class="small-text">Browse 36 films spanning the 80s and 90s, including Carpenter, Spielberg, Zemeckis and Burton favourites. Original VHS scans are used where available; the remaining sleeves use theatrical posters and shop title labels. Browse films opens the artwork and full-size scans. Rain has its own saved setting here. Blue sky is the default; Local time follows your saved location.</p>${btn('Browse films','store-inspect')}${btn('TV view','sky-camera','data-camera="store-tv"')}</div>`:''}${s.settings.background==='cinema'?`<div class="water-settings"><h3>A quiet corner of the 90s</h3><p>Burgundy booths, leafy dividers, palms and familiar fibreglass mascots. Ronald has a seat waiting beside him. Choose a viewpoint, then drag to look around. Press Space or Hide panels for an unobstructed view.</p>${cinemaControlsHTML()}</div>`:''}${s.settings.background==='forest'?`<div class="water-settings"><h3>A quiet stop in the forest</h3><p>Tall trees, a misty road and warm lamplight after dusk. Drag to look around, or use Face bus stop to return to the opening view. Rain starts on here and has its own saved setting. Calm mode pauses the scenery.</p><div class="sky-camera-tools">${btn('Face bus stop','sky-camera','data-camera="stop"')}</div></div>`:''}${s.settings.background==='water'?`<div class="water-settings"><h3>Let the wave carry you</h3><p>Gentle water stretches to the horizon. A distant wave grows steadily closer over 20 minutes of active viewing, then accelerates, draws you rapidly up its face and carries you smoothly over the crest. Afterwards it recedes towards the opposite horizon while the next wave begins its journey.</p><div class="sky-camera-tools">${btn(s.settings.waterRide?'Pause tidal wave':'Resume tidal wave','water-ride',`aria-pressed="${s.settings.waterRide}"`)}${btn('Try a wave now','water-preview')}${btn('Face the wave','sky-camera','data-camera="wave"')}</div><p class="small-text">The cycle pauses while this background is hidden, when the wave is paused, and in Calm mode or reduced motion. Reopening the app starts a fresh cycle. Try a wave now brings the distant wave closer immediately; the crest arrives in about 96 seconds. The next 20-minute interval starts from that crest.</p></div>`:''}</section>`;}
function mallControlsHTML(){return `<div class="mall-controls"><span class="mall-still-note">Still view · animation unavailable</span><div class="mall-views" role="group" aria-label="Mall views">${[['atrium','Atrium'],['fountain','Fountain'],['shops','Shopfronts'],['arcade','Arcade']].map(([id,label])=>btn(label,'sky-camera',`data-camera="mall-${id}"`,'glass-button small')).join('')}</div><div class="mall-motion">${btn(s.settings.calm?'Resume scenery':'Pause scenery','mall-pause',`aria-pressed="${s.settings.calm}"`,'glass-button small')}</div></div>`;}
function stormControlsHTML(){return `<div class="storm-controls"><span class="storm-still-note">Still view · animation unavailable</span><div class="storm-views" role="group" aria-label="Stormwatch views">${[['refuge','Refuge'],['window','Storm window'],['fire','Fireside']].map(([id,label])=>btn(label,'sky-camera',`data-camera="storm-${id}"`,'glass-button small')).join('')}</div><div class="storm-motion" role="group" aria-label="Stormwatch motion">${btn(s.settings.stormLightning?'Lightning on':'Lightning off','storm-lightning',`aria-pressed="${s.settings.stormLightning}"`,'glass-button small')}${btn(s.settings.calm?'Resume scenery':'Pause scenery','storm-pause',`aria-pressed="${s.settings.calm}"`,'glass-button small')}</div></div>`;}
function poolControlsHTML(){return `<div class="pool-views" role="group" aria-label="Poolrooms viewpoints"><span class="pool-still-note">Still views · 3D unavailable</span>${[['bend','The bend'],['spillway','Spillway'],['passage','Under the bridge']].map(([id,label])=>btn(label,'sky-camera',`data-camera="pool-${id}"`,'glass-button small')).join('')}</div>`;}
function cinemaControlsHTML(){return `<div class="cinema-views" role="group" aria-label="Restaurant viewpoints">${[['stairs','Stairway'],['gallery','Dining room'],['ronald','Ronald’s bench'],['booths','Booths']].map(([id,name])=>btn(name,'sky-camera',`data-camera="cinema-${id}"`,'glass-button small')).join('')}</div>`;}
function storeControlsHTML(){return `<div class="store-quick-controls"><div>${btn('Play trailers','store-play','','glass-button small')}${btn('Pause','store-pause','','glass-button small')}${btn('Next','store-next','','glass-button small')}${btn('Sound off','store-sound','aria-pressed="false"','glass-button small')}</div><div class="store-views">${btn('Store','sky-camera','data-camera="field"','glass-button small')}${btn('Windows','sky-camera','data-camera="store-window"','glass-button small')}${btn('Posters','sky-camera','data-camera="store-posters"','glass-button small')}${btn('Shelves','sky-camera','data-camera="store-shelf"','glass-button small')}${btn('TV','sky-camera','data-camera="store-tv"','glass-button small')}</div><div>${btn(s.settings.storeLiveTime?'Local time':'Blue sky','store-time',`aria-pressed="${s.settings.storeLiveTime}"`,'glass-button small')}${btn('Browse 36 films','store-inspect','','glass-button small')}</div><span id="trailer-status" role="status">Press Play trailers to switch on the TV.</span><a id="trailer-source" href="https://www.youtube.com/watch?v=5LnPaD-jHdI" target="_blank" rel="noopener noreferrer">Open trailer source</a></div>`;}

function atmosphereControlsHTML(){const water=s.settings.background==='water',forest=s.settings.background==='forest',store=s.settings.background==='video-store',cinema=s.settings.background==='cinema',pool=s.settings.background==='poolrooms',storm=s.settings.background==='stormwatch',mall=s.settings.background==='mall',rain=backgroundRain(s.settings);return `<div class="atmosphere-controls ${store?'store-controls':''}" role="group" aria-label="Background and atmosphere"><label class="background-picker"><span class="visually-hidden">Background</span><select id="background-select" aria-label="Background">${Object.entries(BACKGROUNDS).map(([id,b])=>`<option value="${id}" ${s.settings.background===id?'selected':''}>${b.name}</option>`).join('')}</select></label>${store||cinema||pool||storm||mall?'':water?btn(icon(s.settings.waterRide?'pause':'play')+(s.settings.waterRide?' Pause wave':' Resume wave'),'water-ride',`aria-pressed="${s.settings.waterRide}"`,'glass-button'):btn(icon('leaf')+(s.settings.breeze?' Breeze on':' Breeze off'),'breeze',`aria-pressed="${s.settings.breeze}"`,'glass-button')}${cinema||pool||mall?'':btn(icon('rain')+(rain?' Rain on':' Rain off'),'rain',`aria-pressed="${rain}"`,'glass-button')}<span id="sky-clock" class="sky-clock"></span>${water?`<div class="water-quick-controls">${btn('Face wave','sky-camera','data-camera="wave"','glass-button small')}${btn('Try a wave','water-preview','','glass-button small')}<span id="water-status">A wave every 20 minutes</span></div>`:''}${forest?btn('Face bus stop','sky-camera','data-camera="stop"','glass-button small'):''}${store?storeControlsHTML():''}${cinema?cinemaControlsHTML():''}${pool?poolControlsHTML():''}${storm?stormControlsHTML():''}${mall?mallControlsHTML():''}${s.settings.calm?'<span class="motion-note">Scenery paused · Calm mode</span>':''}</div>`;}

function skySettings(){const p=s.settings.skyLocation;return `<section class="card padded"><h2>Sky & location</h2><p>Outdoor skies follow the real date and time, with seasonal dawn and dusk. After Hours Video starts with blue sky; its Local time control makes the windows follow your saved location. The shop lights stay on. In the meadow, balloons and leaves finish at sunset and fireflies appear as it gets dark.</p><p class="sky-reading" id="sky-details">${e(skyDetails(currentSky(p)))}</p><p class="small-text">The meadow shows the real local moon phase and position when it is above the horizon. Water planet has its own cinematic moon every night, lighting the water and wave even on moonless dates. The forest lamp comes on at dusk. Rain softens the moonlight and hides the stars.</p><div class="sky-camera-tools">${['video-store','cinema','poolrooms','stormwatch','mall'].includes(s.settings.background)?'':btn('Sky view','sky-camera','data-camera="sky"')+btn('Look at moon','sky-camera','data-camera="moon"')}${btn(s.settings.background==='water'?'Water horizon':s.settings.background==='forest'?'Bus stop view':s.settings.background==='video-store'?'Store view':s.settings.background==='cinema'?'Stairway view':s.settings.background==='poolrooms'?'The bend':s.settings.background==='stormwatch'?'Refuge view':s.settings.background==='mall'?'Atrium view':'Meadow view','sky-camera','data-camera="field"')}</div><p class="sky-location-label"><strong>${e(p.label)}</strong><br><span>${p.latitude.toFixed(3)}°, ${p.longitude.toFixed(3)}°</span></p>${btn(locationPending?'Finding location…':'Use my location','sky-location',locationPending?'disabled':'','primary')}<p class="small-text">Use your device location once, or enter coordinates below. The saved coordinates stay in this browser and are included in your backup. There is no continuous location tracking. Update them if you travel.</p><details><summary>Set location manually</summary><form id="sky-location-form"><div class="field"><label for="sky-place">Location name</label><input class="input" id="sky-place" name="label" value="${e(p.label)}" maxlength="60"></div><div class="form-row"><div class="field"><label for="sky-latitude">Latitude</label><input class="input" id="sky-latitude" name="latitude" type="number" min="-90" max="90" step="any" value="${p.latitude}" required><small>South is negative.</small></div><div class="field"><label for="sky-longitude">Longitude</label><input class="input" id="sky-longitude" name="longitude" type="number" min="-180" max="180" step="any" value="${p.longitude}" required><small>East is positive.</small></div></div><div class="dialog-actions"><button class="btn primary" type="submit">Save location</button>${btn('Reset to Gympie area','sky-location-reset')}</div></form></details><p class="small-text">The sky uses this device’s clock and the saved coordinates. The task day boundary is a separate preference. Stars are decorative. The sun and meadow moon follow astronomy calculations; the water-world moon is artistic. Daycraft 1.20.0.</p></section>`;}
const notebook=createProblemBook({state:()=>s,day:()=>day,uid,e,icon,areaTag,openDialog,closeDialog,render,commit,toast,enter:()=>{overlay.show();if(view!=='problems')clearWorldDraft();view='problems';}});
function render(){
 day=today();
 const scroll=renderedView===view?(document.querySelector('#main')?.scrollTop||0):0;
 app.innerHTML=`${worldBackdropHTML(s,view==='world')}<div id="meadow-interface" class="meadow-interface"><header class="meadow-header"><div class="brand"><img src="./icon.svg" alt=""><span>daycraft</span><small class="app-version">1.20.0</small></div><span class="meadow-name">${e(s.settings.background==='meadow'?s.settings.worldName:BACKGROUNDS[s.settings.background].name)}</span><div class="meadow-header-actions">${view==='problems'?btn(icon('plus')+' Add problem','pb-new','','primary'):btn(icon('plus')+' Add task','add','','primary')}</div></header>${atmosphereControlsHTML()}<main class="meadow-panel content" id="main" tabindex="-1" aria-label="${view==='world'?'Collection and placement':view==='today'?'Today’s tasks':view==='progress'?'Your progress':view==='settings'?'Settings':view==='problems'?'Your problems':'Your tasks'}" data-panel="${view}">${s.settings.background!=='mall'&&view!=='problems'?`<div class="store-new"><span>New scene · Mall atrium</span>${btn('Open','background','data-background="mall"','small')}</div>`:''}${storageIssue?`<div class="notice error" role="alert">${e(storageIssue)}</div>`:''}${s.focus?`<div class="focus-ribbon">${icon('clock')}<span id="focus-status">Your focus block is ${s.focus.paused?'paused':'in progress'}.</span>${btn('Return','resume','','small')}</div>`:''}${({today:renderToday,tasks:renderTasks,problems:notebook.page,world:renderWorld,progress:renderProgress,settings:renderSettings}[view])()}<p class="footer-note">Saved in this browser · finish the result, then take the next task.</p></main><nav class="meadow-nav" aria-label="Main navigation">${[['today','sun','Today'],['tasks','tasks','Tasks'],['problems','problems','Problems'],['world','world','Collection'],['progress','chart','Progress'],['settings','settings','Settings']].map(([id,ic,name])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${name}</span></button>`).join('')}</nav><div class="meadow-hint">Drag to look around <span>·</span> Scroll or pinch to zoom</div></div><button type="button" id="panel-toggle" class="btn panel-toggle" data-action="panels" aria-controls="meadow-interface" aria-expanded="true">Hide panels <kbd>Space</kbd></button>`;
 const panel=document.querySelector('#main');if(panel)panel.scrollTop=scroll;
 renderedView=view;overlay.mount();
 updateSkyUI();refreshTrailerControls();
 mountWorldViews({state:s,render,commit,toast,showPanels:overlay.show});
 window.dispatchEvent(new Event('daycraft:rendered'));
}
function nextTask(){return forToday(s,day).find(t=>!t.blocked)||null;}
function backlog(){return prioritise(s.tasks.filter(t=>t.repeat==='none'&&!isDone(s,t,day)&&!isScheduled(t,day)&&(!t.planned||t.planned<=day)&&!t.blocked),day);}
function paceMessage(w){
 if(w.beforeDay)return `Workday starts at ${timeInput(w.cfg.startMinutes)}. Prepare the full queue now.`;
 if(w.afterDay)return w.pending.length?`Workday ended: ${w.pending.length} tasks remain. Review deadlines and set the next plan.`:'Today’s committed queue is clear.';
 if(w.targetMet)return w.pending.length?`Target reached. ${w.pending.length} committed tasks still need a result.`:'Target reached and committed queue cleared. Pull the next useful task when ready.';
 if(w.gap>=15)return `Behind the target pace by ${minutesLabel(w.gap)} of estimated work. Start the next priority.`;
 return `${minutesLabel(Math.max(0,w.cfg.targetMinutes-w.completedMinutes))} of estimated work to target. Keep the queue moving.`;
}
function renderToday(){
 const all=forToday(s,day),w=workload(s,day,all),done=w.done,waiting=w.blocked,next=nextTask(),active=s.tasks.find(t=>t.id===s.focus?.taskId),t=active||next,extra=backlog(),cfg=w.cfg;
 return heading('Execute today’s plan.','Complete the full workload. Clear deadlines. Keep moving to the next result.',btn('Set daily target','daily-target','','small'))+`
 <div class="execution-strip" aria-label="Today’s execution totals">
  <div><strong>${done.length}<small> / ${done.length+all.length}</small></strong><span>tasks completed</span></div>
  <div><strong>${minutesLabel(w.completedMinutes)}<small> / ${minutesLabel(cfg.targetMinutes)}</small></strong><span>estimated work completed</span></div>
  <div class="${w.overdue.length?'urgent-number':''}"><strong>${w.overdue.length}</strong><span>overdue tasks</span></div>
  <div><strong>${w.mustDo.length}</strong><span>must-do tasks remaining</span></div>
 </div>
 <div class="execution-target" role="progressbar" aria-label="Completed estimated work against daily target" aria-valuenow="${Math.min(100,Math.round(w.completedMinutes/cfg.targetMinutes*100))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,w.completedMinutes/cfg.targetMinutes*100)}%"></span></div>
 <div class="pace-banner ${w.gap>=15&&!w.beforeDay?'behind':''}"><strong id="pace-copy">${e(paceMessage(w))}</strong><span>Estimates measure task size, not verified hours worked.${done.some(c=>!c.estimatedMinutes)?' Older completions without recorded estimates count as tasks only.':''}</span></div>
 <section class="card next-card execution-next"><p class="eyebrow">${icon(active?'clock':'flag')} ${active?'Current focus block':t?'Next priority':'Queue review'}</p>
 ${t?`<div class="task-meta">${priorityBadge(t)}${areaTag(t.area)}<span>${t.minutes} min estimate</span>${t.mustDo?'<span class="must-tag">Must do</span>':''}</div><h2>${e(t.title)}</h2><p>${e(t.reason||'Finish the defined result before moving on.')}</p><div class="step-box"><span>Next action</span>${e(t.step||t.title)}</div><div class="execution-actions">${btn(icon('play')+(active?' Resume focus block':` Start ${Math.round(focusSeconds(s,t)/60)}-minute block`),active?'resume':'start',active?'':`data-id="${e(t.id)}"`,'primary')}${btn('Mark complete','finish',`data-id="${e(t.id)}"`)}${btn('Resolve a blocker','block',`data-id="${e(t.id)}"`,'text')}</div>`:`<h2>${waiting.length?'Resolve the blockers or pull another task.':done.length?'Committed queue cleared.':'Build the full day’s queue.'}</h2><p>${waiting.length?`${waiting.length} tasks are waiting. Record a follow-up action and date for each.`:extra.length?`${extra.length} tasks are available in your backlog.`:'Add the work that needs to ship today. There is no three-task limit.'}</p><div class="execution-actions">${extra[0]?btn('Start next from backlog','start',`data-id="${e(extra[0].id)}"`,'primary'):btn('Add task list','bulk-add','','primary')}${btn('Review all tasks','nav','data-view="tasks"')}</div>`}
 </section>
 <div class="below execution-below"><section><div class="section-heading"><div><h2>Today’s workload <span class="sub">${all.length} open</span></h2><p>Overdue → due today → must-do → priority. ${minutesLabel(w.remainingMinutes)} estimated remaining.</p></div><div class="execution-actions">${btn('Add list','bulk-add','','small')}${btn(icon('plus'),'add','aria-label="Add a task for today"','small')}</div></div>
 ${w.overloaded&&all.length?`<div class="capacity-note">${minutesLabel(w.remainingMinutes)} of work remains in ${minutesLabel(w.availableMinutes)} of the configured day. Decide what to finish, delegate, or replan.</div>`:''}
 ${w.followUps.length?`<div class="capacity-note">${w.followUps.length} blocker follow-up${w.followUps.length===1?' is':'s are'} due. Take the recorded action and update the task.</div>`:''}
 ${all.length?`<div class="task-list">${all.map(taskRow).join('')}</div>`:emptyToday()}
 ${done.length?`<details class="execution-history"><summary>Completed today · ${done.length}</summary><div class="task-list">${done.slice().reverse().map(historyRow).join('')}</div></details>`:''}
 </section><aside>${weekCard()}<section class="card padded execution-rules"><h3>Keep the queue moving</h3><p>Finish the result, confirm it, then start the next priority. Every completed task earns a material.</p><p>Blocked work needs a follow-up action. Unfinished one-off tasks carry into the next day.</p>${btn('Capture task list','bulk-add','','wide')}${btn('Review progress','nav','data-view="progress"','text wide')}</section></aside></div>`;
}
function priorityBadge(t){const p=normalisePriority(t.priority);return `<span class="priority-tag priority-${p}">P${p} · ${PRIORITIES[p]}</span>`;}
function emptyToday(){return `<div class="blank"><h3>Build a complete workload.</h3><p>Paste your task list, set priorities and estimates, and mark the outcomes that must be finished.</p>${btn('Add task list','bulk-add','','primary')}${btn('Add one task','add','','text')}</div>`;}
function taskRow(t){return `<article class="task-row ${t.blocked?'blocked':''} ${isOverdue(t,day)?'overdue-task':''}"><button class="task-check" data-action="finish" data-id="${e(t.id)}" aria-label="Complete ${e(t.title)}" ${t.blocked?'disabled':''}></button><div class="task-body"><div class="task-title">${e(t.title)}</div><div class="task-meta">${priorityBadge(t)}${areaTag(t.area)}<span>${t.minutes} min</span>${t.mustDo?'<span class="must-tag">Must do</span>':''}${t.repeat!=='none'?`<span>${icon('repeat')} ${e(t.repeat)}</span>`:''}${t.due?`<span class="${isOverdue(t,day)?'overdue-label':''}">${isOverdue(t,day)?'Overdue · ':''}Due ${dateLabel(t.due)}</span>`:''}${isCarried(t,day)?'<span>Carried forward</span>':''}</div>${t.blocked?`<div class="blocked-note"><strong>Blocked:</strong> ${e(t.blocked)}<br><strong>Follow-up:</strong> ${e(t.blockAction||'Set the next action')}${t.followUp?` · ${t.followUp<day?'Overdue ':''}${dateLabel(t.followUp)}`:''}</div>`:''}</div><div class="task-menu">${t.blocked?btn('Follow up','block',`data-id="${e(t.id)}"`,'small'):btn(icon('play'),'start',`data-id="${e(t.id)}" aria-label="Start ${e(t.title)}"`,'small')}<button class="icon-btn" data-action="task-menu" data-id="${e(t.id)}" aria-label="Options for ${e(t.title)}">${icon('more')}</button></div></article>`;}
function dailyTargetDialog(){const cfg=normaliseDrive(s.settings.drive);openDialog('Set the daily workload.','Choose a target that reflects your actual day. Task count is unlimited.',`<form id="workload-form"><div class="form-row"><div class="field"><label for="daily-target">Target estimated work, minutes</label><input class="input" id="daily-target" name="targetMinutes" type="number" min="15" max="1440" step="15" required value="${cfg.targetMinutes}"><small>480 minutes = eight hours of task estimates. This is not a timesheet.</small></div><div class="field"><label for="focus-length">Focus block, minutes</label><input class="input" id="focus-length" name="focusMinutes" type="number" min="5" max="120" required value="${cfg.focusMinutes}"><small>Short tasks use their shorter estimate.</small></div></div><div class="form-row"><div class="field"><label for="work-start">Workday starts</label><input class="input" type="time" id="work-start" name="start" value="${timeInput(cfg.startMinutes)}" required></div><div class="field"><label for="work-end">Workday ends</label><input class="input" type="time" id="work-end" name="end" value="${timeInput(Math.min(1439,cfg.endMinutes))}" required></div></div><div class="field"><label for="nudge-length">Prompt when no task is running, minutes</label><input class="input" id="nudge-length" name="nudgeMinutes" type="number" min="0" max="60" value="${cfg.nudgeMinutes}" required><small>Works while Daycraft is open during your configured workday. Set 0 to turn prompts off.</small></div><div class="dialog-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">Save workload target</button></div></form>`,'workload');}
function bulkTaskDialog(){openDialog('Capture the full task list.','One task per line. Priorities and estimates can be adjusted individually.',`<form id="bulk-form"><div class="field"><label for="bulk-titles">Tasks</label><textarea class="input" id="bulk-titles" name="titles" rows="9" maxlength="18500" required autofocus placeholder="Confirm delivery dates\nReview tomorrow’s workfront\nSubmit the variation\nClose out the test records"></textarea></div><div class="form-row"><div class="field"><label for="bulk-area">Area</label><select id="bulk-area" name="area">${Object.entries(AREAS).map(([id,a])=>`<option value="${id}">${a.name}</option>`).join('')}</select></div><div class="field"><label for="bulk-minutes">Default estimate, minutes</label><input class="input" id="bulk-minutes" name="minutes" type="number" min="1" max="240" value="15" required></div><div class="field"><label for="bulk-priority">Default priority</label><select id="bulk-priority" name="priority">${Object.entries(PRIORITIES).map(([id,label])=>`<option value="${id}" ${id==='3'?'selected':''}>P${id} · ${label}</option>`).join('')}</select></div></div><label class="check-label"><input type="checkbox" name="planned" checked> Add all to today’s workload</label><div class="dialog-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">Add task list</button></div></form>`,'bulk');}
function historyRow(c){return `<article class="task-row completed"><span class="task-check completed">${icon('check')}</span><div class="task-body"><div class="task-title">${e(c.title)}</div><div class="task-meta">${areaTag(c.area)}<span>${dateLabel(c.day)}</span>${c.credit&&!s.settings.calm?'<span>+1 material</span>':''}</div></div><button class="icon-btn" data-action="undo" data-id="${e(c.id)}" aria-label="Undo completion of ${e(c.title)}">${icon('back')}</button></article>`;}
function weekData(){const days=Array.from({length:7},(_,i)=>shiftDate(day,i-6));return {days,events:s.completions.filter(c=>days.includes(c.day)),starts:s.starts.filter(c=>days.includes(c.day))};}
function weekCard(){const w=weekData();return `<section class="card weekly-card"><div class="row-between"><h3>Your last seven days</h3>${icon('chart')}</div><p>Completed results across the last seven days.</p><div class="week-dots">${w.days.map(d=>{const n=w.events.filter(c=>c.day===d).length;return `<div class="day-dot ${n?'active':''} ${d===day?'today':''}" title="${dateLabel(d)}: ${n} actions"><div class="dot">${n||''}</div>${dateLabel(d,{weekday:'narrow'})}</div>`;}).join('')}</div><div class="week-stats"><div><strong>${w.events.length}</strong><span>actions finished</span></div><div><strong>${new Set(w.events.map(c=>c.day)).size}</strong><span>days with progress</span></div></div></section>`;}
function renderTasks(){let tasks=s.tasks.filter(t=>taskTab==='today'?isScheduled(t,day)&&!isDone(s,t,day):taskTab==='waiting'?!!t.blocked&&!isDone(s,t,day):!isDone(s,t,day));tasks=prioritise(tasks,day).filter(t=>(areaFilter==='all'||t.area===areaFilter)&&(!query||t.title.toLowerCase().includes(query.toLowerCase())));let history=s.completions.filter(c=>(areaFilter==='all'||c.area===areaFilter)&&(!query||c.title.toLowerCase().includes(query.toLowerCase()))).slice().reverse();return heading('Full task list.','Capture the whole workload. Prioritise it, then execute.',btn('Add task list','bulk-add','','small'))+`<div class="filters"><div class="tabs" role="group" aria-label="Task filter">${[['all','All tasks'],['today','Today'],['waiting','Waiting'],['done','Completed']].map(([id,l])=>`<button data-action="task-tab" data-value="${id}" class="${taskTab===id?'active':''}" aria-pressed="${taskTab===id}">${l}</button>`).join('')}</div><label class="visually-hidden" for="area-filter">Filter by area</label><select id="area-filter" style="width:150px"><option value="all">All areas</option>${Object.entries(AREAS).map(([id,a])=>`<option value="${id}" ${areaFilter===id?'selected':''}>${a.name}</option>`).join('')}</select></div><label class="visually-hidden" for="task-search">Search tasks</label><input id="task-search" class="input search" value="${e(query)}" placeholder="Find a task…" type="search" style="margin-bottom:19px"><p class="pb-task-link">Not sure what action to take? ${btn('Work through a problem','pb-new','','text small')}</p><div id="task-results" class="task-list">${taskTab==='done'?history.length?history.map(historyRow).join(''):blank('A record of the things you finish.','Your completed actions will appear here.'):tasks.length?tasks.map(taskRow).join(''):blank('No tasks in this view.','Capture the next workload or choose another filter.')}</div>`;}
function blank(title,message){return `<div class="blank"><h3>${title}</h3><p>${message}</p>${btn(icon('plus')+' Add a task','add','','soft')}</div>`;}
function renderWorld(){return worldPageHTML(s);}
function renderProgress(){const w=weekData(),review=s.reviews.find(x=>x.day===day),previous=s.reviews.slice().sort((a,b)=>a.day.localeCompare(b.day))[0];return heading('Review execution.','Track completed outcomes, workload and what needs to change.')+`<div class="stat-grid"><div class="card stat-card"><p class="eyebrow">Last 7 days</p><strong>${minutesLabel(w.events.reduce((n,c)=>n+(c.estimatedMinutes||0),0))}</strong><p>estimated work completed</p></div><div class="card stat-card"><p class="eyebrow">Last 7 days</p><strong>${w.events.length}</strong><p>actions completed</p></div><div class="card stat-card"><p class="eyebrow">All time</p><strong>${earned(s)}</strong><p>materials earned from actions</p></div></div>${notebook.progress()}<div class="two-cols"><div class="stack">${weekCard()}<section class="card padded"><h2>Space for every part of life.</h2><p>Actions completed in the last seven days. This is a record, not a ranking of what matters.</p>${Object.entries(AREAS).map(([id,a])=>{const n=w.events.filter(c=>c.area===id).length;return `<div class="area-progress" style="--area:${a.color}"><span style="width:45px">${a.name}</span><div class="bar"><span style="width:${w.events.length?n/w.events.length*100:0}%"></span></div><strong>${n}</strong></div>`;}).join('')}</section></div><section class="card padded"><h2>End-of-day review</h2><p>Identify what shipped, what slipped, and what you will change tomorrow.</p><form id="review-form"><label class="small-text">Compared with a usual day, delivering the work felt…</label><div class="review-grid">${[['easier','Easier'],['same','About the same'],['harder','Harder']].map(([id,l])=>`<label><input type="radio" name="feeling" value="${id}" ${review?.feeling===id?'checked':''} required>${l}</label>`).join('')}</div><label class="small-text">The app’s expectations felt…</label><div class="review-grid">${[['too-soft','Needs more push'],['okay','Right level'],['too-much','Overcommitted']].map(([id,l])=>`<label><input type="radio" name="pressure" value="${id}" ${review?.pressure===id?'checked':''} required>${l}</label>`).join('')}</div><div class="field"><label for="review-note">What shipped, what slipped, and what changes tomorrow? <span class="small-text">Optional</span></label><textarea id="review-note" name="note" maxlength="500" placeholder="E.g. Close out outstanding approvals before the next workfront starts.">${e(review?.note||'')}</textarea></div><button class="btn primary" type="submit">${review?'Update check-in':'Save check-in'}</button></form>${previous?`<div class="rule"></div><p class="small-text">First check-in, ${dateLabel(previous.day)}: starting felt ${previous.feeling==='same'?'about the same':e(previous.feeling)}; expectations ${previous.pressure==='okay'?'right level':previous.pressure==='too-soft'?'needs more push':'overcommitted'}.</p>`:''}${review?`<div class="notice" style="margin-top:16px">Use the review to adjust the workload, resolve recurring blockers, or tighten priorities.</div>${btn('Adjust daily target','daily-target','','soft')}`:''}</section></div><div class="section-heading" style="margin-top:27px"><h2>Recent progress</h2></div><div class="task-list">${s.completions.length?s.completions.slice(-10).reverse().map(historyRow).join(''):blank('Your story starts with one action.','There is no past score to catch up with.')}</div>`;}
function renderSettings(){return heading('Configure your workday.','Set the target, focus rhythm and environment.')+`<div class="two-cols settings-wide"><div class="stack"><section class="card padded"><h2>Execution settings</h2><p>${minutesLabel(s.settings.drive.targetMinutes)} daily target · ${s.settings.drive.focusMinutes}-minute focus blocks · unlimited tasks.</p>${btn('Set workload and prompts','daily-target','','primary')}</section><section class="card padded"><h2>Your space</h2><p class="small-text">Use Space or Hide panels to enjoy your chosen background. Choose Meadow, Water planet, Forest bus stop, After Hours Video, 90s Macca’s or Poolrooms above the scene or below. Rain is available outside the shop windows as well as in the outdoor scenes.</p><form id="settings-form"><div class="field"><label for="name">Your name</label><input class="input" id="name" name="name" value="${e(s.settings.name)}" maxlength="40" required></div><div class="field"><label for="world-name">World name</label><input class="input" id="world-name" name="worldName" value="${e(s.settings.worldName)}" maxlength="50" required></div><div class="field"><label for="timezone">Day boundary</label><select id="timezone" name="zone">${[...new Set([s.settings.zone,'Australia/Brisbane','Australia/Sydney','Australia/Perth','UTC'])].map(z=>`<option value="${e(z)}" ${z===s.settings.zone?'selected':''}>${e(z.replaceAll('_',' '))}</option>`).join('')}</select><small>Today’s queue and completion totals use this timezone. Incomplete one-off tasks carry forward.</small></div><div class="field"><label class="check-label"><input type="checkbox" name="calm" ${s.settings.calm?'checked':''}> Calm mode</label><small>Pause scenery movement, wave rides and soften reward labels. Fireflies become still glows. The sky still follows the real time. Your device’s reduced-motion preference also pauses movement.</small></div><button type="submit" class="btn primary">Save preferences</button></form></section>${backgroundSettings()}${skySettings()}<section class="card padded"><h2>Your data</h2><p>Daycraft saves your tasks, problems, inventory and 3D placements in this browser on this device. Your saved progress stays here when you close the app. Each device has its own copy; changes are not synced between devices.</p><p>Use Export backup to keep a copy or transfer your progress to another device. Importing a backup replaces that device’s copy. Backups include your tasks, problems, findings, items, meadows and positions. Export before clearing browser data.</p><div class="dialog-actions" style="justify-content:flex-start">${btn(icon('download')+' Export backup','export')}${btn('Import backup','import')}${btn('Export recovery copy','export-raw','','text')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="rule"></div><p class="small-text">The website is public; your tasks, problems and progress stay in this browser and are not uploaded to GitHub. Anyone using this browser profile can access the saved data. No account, analytics or push notifications.</p></section></div><div class="stack"><section class="card padded"><h2>How progress works</h2><ol class="help-list"><li><strong>Choose a finishable action.</strong> Define the result, estimate the work and set a priority.</li><li><strong>Start, or clear the blocker.</strong> You can pause or stop whenever you need. A timer never marks work complete.</li><li><strong>Check what “finished” means.</strong> Complete it when that result is true. Work actions include any required safety and quality checks.</li><li><strong>Every completed task counts.</strong> Every confirmed result earns one material, with no daily cap. Estimates contribute to your workload target. Task count does not replace a clear finished result.</li><li><strong>Make it yours.</strong> Earned items enter your inventory. In My world, tap to place, rotate or move them. Placement is free. Collect all twelve original places to open six decorations and additional meadows for eight materials each. Additional meadows reuse your available item designs and the three lighting moods.</li><li><strong>Keep what you build.</strong> Taking a break never removes progress. If you undo a mistaken completion, its material is reversed; a recent item or island may be reversed. Items from a reversed island return to inventory.</li></ol></section><section class="card padded"><h2>Run the full day.</h2><p>Capture the workload, mark must-do outcomes and start the highest priority. After each completion, take the next task.</p><p>Overdue and unfinished one-off tasks stay visible. Blockers need a follow-up action and date. The daily target is a planning measure; remaining commitments still matter after it is reached.</p><p class="small-text">Workload minutes come from task estimates, not a measurement of hours worked. The focus timer never marks a task complete.</p></section></div></div>`;}
function openDialog(title,sub,body,kind='generic'){dialogKind=kind;modal.innerHTML=`<div class="dialog-body"><div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</div>`;if(!modal.open)modal.showModal();mountModelPreviews();}
function closeDialog(){modal.close();dialogKind='';}
function taskForm(id=null,preset=null){const isCheck=id&&!!linkForTask(s,id),t=s.tasks.find(t=>t.id===id)||preset||{title:'',area:'work',step:'',doneMeans:'',minutes:15,repeat:'none',planned:day,reason:'',due:''};openDialog(id?'Edit the task.':'Add a task.','Define the result, priority and next action.',`<form id="task-form" data-id="${e(id||'')}"><div class="field"><label for="task-title">Task or deliverable</label><input class="input" id="task-title" name="title" value="${e(t.title)}" maxlength="180" placeholder="E.g. Draft tomorrow’s work plan" required autofocus></div><div class="field"><label for="first-step">Next action</label><input class="input" id="first-step" name="step" value="${e(t.step)}" maxlength="250" placeholder="E.g. Open the plan and write the first activity" required></div><div class="form-row"><div class="field"><label for="task-area">Part of life</label><select id="task-area" name="area">${Object.entries(AREAS).map(([id,a])=>`<option value="${id}" ${t.area===id?'selected':''}>${a.name}</option>`).join('')}</select></div><div class="field"><label for="task-time">Estimated work, minutes</label><input class="input" id="task-time" name="minutes" type="number" min="1" max="240" value="${t.minutes||15}" required></div></div><div class="form-row"><div class="field"><label for="task-priority">Priority</label><select id="task-priority" name="priority">${Object.entries(PRIORITIES).map(([id,label])=>`<option value="${id}" ${Number(id)===normalisePriority(t.priority)?'selected':''}>P${id} · ${label}</option>`).join('')}</select></div><div class="field"><label class="check-label"><input type="checkbox" name="mustDo" ${t.mustDo?'checked':''}> Must finish today</label></div></div><div class="field"><label for="done-means">Finished means…</label><input class="input" id="done-means" name="doneMeans" value="${e(t.doneMeans)}" maxlength="400" placeholder="E.g. Three activities, their owners and blockers are listed" required><small>Include any checks that matter. This is what you’ll confirm at the end.</small></div><details ${id?'open':''}><summary>Repeat, purpose & due date</summary><div class="form-row"><div class="field"><label for="task-repeat">Repeat</label><select id="task-repeat" name="repeat" ${isCheck?'disabled aria-describedby="one-check-note"':''}>${[['none','One-off'],['daily','Every day'],['weekdays','Weekdays'],['weekly','Weekly, '+dateLabel(shiftDate(day,(t.weekday??dayOfWeek(day))-dayOfWeek(day)),{weekday:'long'})]].map(([id,l])=>`<option value="${id}" ${t.repeat===id?'selected':''}>${l}</option>`).join('')}</select>${isCheck?'<small id="one-check-note">A problem check is a one-off task.</small>':''}</div><div class="field"><label for="task-due">Due date <span class="small-text">Optional</span></label><input class="input" id="task-due" name="due" type="date" value="${e(t.due)}"></div></div><div class="field"><label for="task-reason">Why this matters to you <span class="small-text">Optional</span></label><input class="input" id="task-reason" name="reason" value="${e(t.reason)}" maxlength="250" placeholder="E.g. A calmer start for the crew tomorrow"></div></details><label class="check-label"><input name="planned" type="checkbox" ${t.planned===day?'checked':''}> Put this in today’s plan</label><div class="dialog-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">${id?'Save task':'Add to my tasks'}</button></div></form>`,'task');}
function taskMenu(id){const t=s.tasks.find(t=>t.id===id);if(!t)return;const link=linkForTask(s,id);openDialog(e(t.title),'Set priority, plan the work, or clear the blocker.',`<div class="stack">${link?btn(icon('problems')+' Open linked problem','pb-open',`data-id="${e(link.problem.id)}"`):''}${btn(icon('edit')+' Edit task','edit',`data-id="${e(id)}"`)}${btn(t.mustDo?'Remove must-do flag':'Mark must-do today','must-do',`data-id="${e(id)}"`)}${btn(isScheduled(t,day)?'Remove from today’s plan':'Put in today’s plan','plan',`data-id="${e(id)}"`)}${btn(icon('block')+(t.blocked?' Clear blocker':' Something is blocking me'),t.blocked?'unblock':'block',`data-id="${e(id)}"`)}${btn('Delete task','delete',`data-id="${e(id)}"`,'danger')}</div>`);}
function finishDialog(id){const t=s.tasks.find(x=>x.id===id);if(!t)return;if(t.blocked){toast('Clear the blocker before finishing this task.');return;}openDialog('Confirm the completed result.',e(t.title),`<div class="done-definition"><p class="eyebrow">Finished means</p>${e(t.doneMeans||t.title)}</div><p class="small-text">Confirm the result is complete, including any required safety and quality checks. The timer does not decide this for you.</p><div class="dialog-actions">${btn('Keep working','close')}${btn(icon('check')+' Yes, it’s finished','confirm-finish',`data-id="${e(id)}"`,'primary')}</div>`,'finish');}
function blockDialog(id){const t=s.tasks.find(x=>x.id===id);if(!t)return;openDialog('Resolve the blocker.','Give the waiting task a concrete follow-up.',`<form id="block-form" data-id="${e(id)}"><div class="field"><label for="block-reason">What is preventing completion?</label><input class="input" id="block-reason" name="reason" maxlength="250" value="${e(t.blocked)}" placeholder="E.g. Supplier has not confirmed dispatch" required></div><div class="field"><label for="block-action">Next follow-up action</label><input class="input" id="block-action" name="blockAction" maxlength="250" value="${e(t.blockAction)}" placeholder="E.g. Call dispatch for an ETA" required></div><div class="field"><label for="follow-up">Follow-up date</label><input class="input" id="follow-up" type="date" name="followUp" value="${e(t.followUp||day)}" required></div><div class="dialog-actions">${t.blocked?btn('Blocker cleared','unblock',`data-id="${e(id)}"`):btn('Cancel','close')}<button class="btn primary" type="submit">Save follow-up</button></div></form>`,'block');}
function start(id){const t=s.tasks.find(x=>x.id===id);if(!t||t.blocked||isDone(s,t,day))return;if(s.focus&&s.focus.taskId!==id){openDialog('A focus block is already running.','Choose where to put your attention.',`<div class="dialog-actions">${btn('Return to current task','resume')}${btn('Switch to this task','switch-focus',`data-id="${e(id)}"`,'primary')}</div>`);return;}if(!s.focus){const seconds=focusSeconds(s,t);lastPromptAt=Date.now();t.planned=day;s.focus={taskId:id,end:Date.now()+seconds*1000,remaining:seconds,paused:false,duration:seconds};logStart(s,id,day);commit();}focusDialog();}
function focusDialog(){const t=s.tasks.find(x=>x.id===s.focus?.taskId);if(!t){s.focus=null;commit();closeDialog();return;}openDialog('Focus on the result.','One task. Work the block, then confirm the outcome or continue.',`<div class="focus-view"><span class="tag">${areaTag(t.area)}</span><h3>${e(t.title)}</h3><div class="step-box"><span>Next action</span>${e(t.step||t.title)}</div><div id="clock" class="timer" role="timer" aria-label="Time remaining">—</div><p id="timer-caption">Work toward the defined result. The timer does not complete the task.</p><div class="timer-controls">${btn(icon('pause')+' Pause','pause','','soft')}${btn('+ 10 minutes','extend')}</div>${btn(icon('check')+' I finished the task','finish',`data-id="${e(t.id)}"`,'primary wide')}${btn('End block · keep task open','stop-focus','','text')}</div>`,'focus');tick();}
function tick(){if(!document.hidden)updateSkyUI();if(s.focus){const status=document.querySelector('#focus-status');if(status)status.textContent=s.focus.paused?'Focus block paused.':s.focus.end<=Date.now()?'Focus block ended. Confirm the result or continue.':'Focus block in progress.';const key=s.focus.taskId+':'+s.focus.end;if(!document.hidden&&!s.focus.paused&&s.focus.end<=Date.now()&&focusAlerted!==key){focusAlerted=key;toast('Focus block ended. Confirm the result, continue working, or resolve the blocker.');}const remaining=s.focus.paused?s.focus.remaining:Math.max(0,Math.ceil((s.focus.end-Date.now())/1000));const clock=document.querySelector('#clock');if(clock&&dialogKind==='focus'){clock.textContent=`${Math.floor(remaining/60).toString().padStart(2,'0')}:${(remaining%60).toString().padStart(2,'0')}`;document.querySelector('#timer-caption').textContent=s.focus.paused?'Paused. Resume this block or choose the next action deliberately.':remaining===0?'Block ended. Confirm the result, extend the block, or resolve a blocker.':'Work toward the defined result. The timer does not complete the task.';const b=modal.querySelector('[data-action="pause"]');b.innerHTML=icon(s.focus.paused?'play':'pause')+(s.focus.paused?' Resume':' Pause');}}if(today()!==day){render();}if(Date.now()-lastPaceAt<30000)return;lastPaceAt=Date.now();const summary=workload(s,day,forToday(s,day));const pace=document.querySelector('#pace-copy');if(pace)pace.textContent=paceMessage(summary);const editing=document.activeElement?.matches?.('input,textarea,select,[contenteditable]');if(mayPrompt({now:Date.now(),lastPrompt:lastPromptAt,hidden:document.hidden,dialogOpen:!!dialogKind||!!editing,focus:s.focus,summary})){lastPromptAt=Date.now();const task=summary.ready[0];openDialog('Keep the workload moving.',`${summary.pending.length} tasks remain. Start the next priority.`,`<h3>${e(task.title)}</h3><div class="task-meta">${priorityBadge(task)}<span>${task.minutes} min estimate</span></div><div class="dialog-actions">${btn('Snooze '+summary.cfg.nudgeMinutes+' min','close')}${btn('Start this task','start',`data-id="${e(task.id)}"`,'primary')}</div>`,'accountability');}}
function download(data,name='daycraft-backup-'+day+'.json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const presets={work:{title:'Draft tomorrow’s work plan',step:'Open the plan and write the first activity.',doneMeans:'The key activities, owners and known blockers are written down.',minutes:15,reason:'Make tomorrow’s start feel more organised.'},health:{title:'Take a short walk',step:'Put on your shoes and step outside.',doneMeans:'I took the short walk I planned, at a comfortable pace.',minutes:10,reason:'Make a little room to move and clear my head.'},life:{title:'Reset one small space',step:'Choose one surface and put three things away.',doneMeans:'The one space I chose is tidy and ready to use.',minutes:10,reason:'Make home feel a little calmer.'}};
async function handleAction(action,el){if(action.startsWith('pb-')){notebook.action(action,el);return;}const id=el.dataset.id;switch(action){
 case 'panels':overlay.toggle();break;
 case 'background':chooseBackground(el.dataset.background);break;
 case 'store-play':trailerAction('play');break;
 case 'store-pause':trailerAction('pause');break;
 case 'store-next':trailerAction('next');break;
 case 'store-sound':trailerAction('sound');break;
 case 'store-inspect':openDialog('The After Hours collection','Carpenter, Spielberg, Zemeckis, Burton and more.',vhsInspectorHTML(e)+`<div class="dialog-actions">${btn('Close','close')}</div>`);break;
 case 'store-film':openDialog('Film artwork','Original cover scans and theatrical posters.',vhsFilmHTML(el.dataset.film,e));break;
 case 'store-time':s.settings.storeLiveTime=!s.settings.storeLiveTime;commit();document.querySelector('[data-action="store-time"]')?.focus?.();break;
 case 'water-ride':s.settings.waterRide=!s.settings.waterRide;commit();document.querySelector('[data-action="water-ride"]')?.focus?.();break;
 case 'water-preview':{const message=previewWaterWave();toast(message||'The wave is coming closer. Its crest arrives in about 96 seconds; you can look around during the ride.');break;}
 case 'sky-camera':if(!cameraAction(el.dataset.camera))toast(el.dataset.camera==='moon'?(s.settings.background==='water'?'The water-world moon appears after dark.':'The moon is below the horizon for your saved location right now.'):'The 3D view is not available right now.');break;
 case 'sky-location':{const request=++locationRequest;locationPending=true;el.disabled=true;el.textContent='Finding location…';try{const place=await requestSkyLocation();if(request!==locationRequest)break;s.settings.skyLocation=place;locationPending=false;commit();toast('Location saved. Your sky now follows this place.');}finally{if(request===locationRequest){locationPending=false;const b=document.querySelector('[data-action="sky-location"]');if(b){b.disabled=false;b.textContent='Use my location';}}}break;}
 case 'sky-location-reset':locationRequest++;locationPending=false;s.settings.skyLocation={...DEFAULT_SKY_LOCATION};commit();toast('Sky location reset to the approximate Gympie area.');break;
 case 'storm-lightning':s.settings.stormLightning=!s.settings.stormLightning;commit();document.querySelector('[data-action="storm-lightning"]')?.focus?.();break;
 case 'mall-pause':s.settings.calm=!s.settings.calm;commit();document.querySelector('[data-action="mall-pause"]')?.focus?.();break;
 case 'storm-pause':s.settings.calm=!s.settings.calm;commit();document.querySelector('[data-action="storm-pause"]')?.focus?.();break;
 case 'rain':if(s.settings.background==='stormwatch')s.settings.stormRain=!backgroundRain(s.settings);else if(s.settings.background==='video-store')s.settings.storeRain=!backgroundRain(s.settings);else if(s.settings.background==='forest')s.settings.forestRain=!backgroundRain(s.settings);else s.settings.rain=!s.settings.rain;commit();document.querySelector('[data-action="rain"]')?.focus?.();break;
 case 'breeze':s.settings.breeze=!s.settings.breeze;commit();document.querySelector('[data-action="breeze"]')?.focus?.();break;
 case 'nav':overlay.show();clearWorldDraft();view=el.dataset.view;if(view==='problems')notebook.listView();query='';render();window.scrollTo({top:0,behavior:'instant'});break;
 case 'add':taskForm();break;case 'suggest':taskForm(null,{...presets[el.dataset.area],area:el.dataset.area,repeat:'none',planned:day,due:''});break;
 case 'close':closeDialog();break;case 'daily-target':dailyTargetDialog();break;case 'bulk-add':bulkTaskDialog();break;case 'must-do':{const t=s.tasks.find(t=>t.id===id);if(t){t.mustDo=!t.mustDo;if(t.mustDo)t.planned=day;}closeDialog();commit();break;}
 case 'task-tab':taskTab=el.dataset.value;render();break;case 'task-menu':taskMenu(id);break;case 'edit':taskForm(id);break;
 case 'plan':{const t=s.tasks.find(x=>x.id===id);if(isScheduled(t,day)){if(t.repeat!=='none'||t.mustDo||(t.due&&t.due<=day)){toast('This task has a repeat, deadline or must-do commitment. Edit the task to replan it.');taskForm(id);return;}t.planned='';}else t.planned=day;closeDialog();commit();break;}
 case 'delete':openDialog('Delete this task?','This removes the task and its repeats. Your completed action history stays.',`<div class="dialog-actions">${btn('Keep task','close')}${btn('Delete task','confirm-delete',`data-id="${e(id)}"`,'danger')}</div>`);break;
 case 'confirm-delete':s.tasks=s.tasks.filter(t=>t.id!==id);if(s.focus?.taskId===id)s.focus=null;closeDialog();commit();toast('Task removed. Completed progress is kept.');break;
 case 'block':blockDialog(id);break;case 'unblock':{const t=s.tasks.find(t=>t.id===id);if(t){t.blocked='';t.blockAction='';t.followUp='';}closeDialog();commit();toast('Blocker cleared. Return this task to the execution queue.');break;}
 case 'finish':finishDialog(id);break;
 case 'confirm-finish':{const event=completeTask(s,id,day),link=linkForTask(s,id);lastPromptAt=Date.now();closeDialog();commit();const next=nextTask(),extra=!next?backlog()[0]:null,candidate=next||extra,w=workload(s,day,forToday(s,day));openDialog('Completed. Keep the queue moving.',e(event.title),`<div class="completion-score"><strong>${w.done.length} tasks finished today</strong><span>+1 material · ${minutesLabel(w.completedMinutes)} estimated work completed</span></div>${candidate?`<p class="eyebrow">${next?'Next priority':'Next from backlog'}</p><h3>${e(candidate.title)}</h3><div class="task-meta">${priorityBadge(candidate)}<span>${candidate.minutes} min estimate</span></div>`:`<h3>${w.blocked.length?'Resolve the remaining blockers.':'Today’s committed queue is clear.'}</h3><p>${w.blocked.length?`${w.blocked.length} tasks still need follow-up.`:'Review delivery, or capture the next workload.'}</p>`}<div class="dialog-actions">${btn('Review workload','back-to-work')}${link?btn('Record problem finding','pb-open',`data-id="${e(link.problem.id)}"`):''}${candidate?btn('Start next task','start',`data-id="${e(candidate.id)}"`,'primary'):btn('Add task list','bulk-add','','primary')}</div><p class="small-text">${balance(s)} materials available. ${btn('Open collection','world-after-win','','text small')}</p>`,'win');break;}
 case 'back-to-work':closeDialog();view='today';overlay.show();render();break;
 case 'world-after-win':closeDialog();overlay.show();view='world';render();window.scrollTo(0,0);break;
 case 'undo':openDialog('Undo this completion?','Materials will be recalculated. If a material was already spent, recent item or island purchases may be reversed. Items on a reversed island return to inventory. Nothing changes because of a missed day.',`<div class="dialog-actions">${btn('Keep completion','close')}${btn('Undo completion','confirm-undo',`data-id="${e(id)}"`,'primary')}</div>`);break;
 case 'confirm-undo':{const removed=undoCompletion(s,id);closeDialog();commit();toast(removed.length?'Completion undone. Recent purchases were reversed; check your inventory.':'Completion undone.');break;}
 case 'build':{const b=build(s,id);closeDialog();view='world';commit();beginEarnedItem(b.instanceId);toast(b.name+' is yours. Choose where to place it.');break;}
 case 'start':start(id);break;case 'resume':focusDialog();break;case 'switch-focus':s.focus=null;start(id);break;
 case 'pause':if(s.focus){if(s.focus.paused){s.focus.end=Date.now()+s.focus.remaining*1000;s.focus.paused=false;}else{s.focus.remaining=Math.max(0,Math.ceil((s.focus.end-Date.now())/1000));s.focus.paused=true;}persist();render();tick();}break;
 case 'extend':if(s.focus){const remain=s.focus.paused?s.focus.remaining:Math.max(0,Math.ceil((s.focus.end-Date.now())/1000));s.focus.remaining=Math.min(14400,remain+600);s.focus.end=Date.now()+s.focus.remaining*1000;s.focus.duration=Math.min(14400,s.focus.duration+600);s.focus.paused=false;persist();tick();}break;
 case 'stop-focus':s.focus=null;closeDialog();commit();lastPromptAt=Date.now();toast('Block ended. The task remains open. Choose the next action.');break;
 case 'export':download(s);toast('Backup downloaded. Keep it somewhere you can find again.');break;
 case 'import':document.querySelector('#import-file')?.click();break;
 case 'confirm-import':if(pendingImport){locationRequest++;locationPending=false;clearWorldDraft();s=pendingImport;pendingImport=null;closeDialog();commit();toast('Your backup is restored in this browser.');}break;
 case 'export-raw':try{download(localStorage.getItem(KEY+'.recovery')||localStorage.getItem(KEY+'.before-productivity')||localStorage.getItem(KEY)||JSON.stringify(s),'daycraft-stored-data.json');}catch{download(s);}break;
 }}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;Promise.resolve(handleAction(el.dataset.action,el)).catch(err=>toast(err.message||'That action could not be completed.'));});
document.addEventListener('submit',ev=>{const form=ev.target;if(form.id?.startsWith('pb-')){ev.preventDefault();try{notebook.submit(form,new FormData(form));}catch(err){toast(err.message||'This problem could not be saved.');}return;}if(!['task-form','block-form','settings-form','sky-location-form','review-form','workload-form','bulk-form'].includes(form.id))return;ev.preventDefault();const f=new FormData(form);
 if(form.id==='task-form'){const id=form.dataset.id,old=s.tasks.find(x=>x.id===id);const repeat=old&&linkForTask(s,id)?'none':f.get('repeat'),changedRepeat=old&&old.repeat!==repeat&&s.completions.some(c=>c.taskId===old.id);const t={id:changedRepeat?uid():id||uid(),title:f.get('title').trim(),area:f.get('area'),step:f.get('step').trim(),doneMeans:f.get('doneMeans').trim(),minutes:Number(f.get('minutes')),repeat,weekday:old?.repeat==='weekly'?old.weekday:dayOfWeek(day),planned:f.has('planned')||f.has('mustDo')?day:'',priority:normalisePriority(f.get('priority')),mustDo:f.has('mustDo'),blockAction:old?.blockAction||'',followUp:old?.followUp||'',due:f.get('due'),reason:f.get('reason').trim(),blocked:old?.blocked||'',createdAt:old?.createdAt||new Date().toISOString()};if(!t.title||!t.step||!t.doneMeans||!Number.isFinite(t.minutes)||t.minutes<1||t.minutes>240||!Object.hasOwn(AREAS,t.area)){toast('Add the task, next action and finished result.');return;}if(old){if(changedRepeat&&s.focus?.taskId===old.id)s.focus=null;Object.assign(old,t);}else{s.tasks.push(t);}closeDialog();commit();toast(old?'Task updated.':'Task added to the workload.');}
 if(form.id==='block-form'){const t=s.tasks.find(x=>x.id===form.dataset.id);if(t){const reason=String(f.get('reason')||'').trim(),action=String(f.get('blockAction')||'').trim(),followUp=String(f.get('followUp')||'');if(!reason||!action||!/^\d{4}-\d{2}-\d{2}$/.test(followUp)||!Number.isFinite(Date.parse(followUp))||new Date(followUp).toISOString().slice(0,10)!==followUp){toast('Add the blocker, follow-up action and date.');return;}t.blocked=reason;t.blockAction=action;t.followUp=followUp;if(s.focus?.taskId===t.id)s.focus=null;}closeDialog();commit();lastPromptAt=Date.now();toast('Follow-up saved. Start the next unblocked task.');}
 if(form.id==='workload-form'){const targetMinutes=Number(f.get('targetMinutes')),focusMinutes=Number(f.get('focusMinutes')),startMinutes=readTime(f.get('start')),endMinutes=readTime(f.get('end')),nudgeMinutes=Number(f.get('nudgeMinutes'));if(![targetMinutes,focusMinutes,startMinutes,endMinutes,nudgeMinutes].every(Number.isFinite)||targetMinutes<15||targetMinutes>1440||focusMinutes<5||focusMinutes>120||endMinutes-startMinutes<30||nudgeMinutes<0||nudgeMinutes>60){toast('Check the target, focus length and workday times. End time must be after start time.');return;}s.settings.drive=normaliseDrive({targetMinutes,focusMinutes,startMinutes,endMinutes,nudgeMinutes});lastPromptAt=Date.now();closeDialog();commit();toast('Daily workload target saved.');}
 if(form.id==='bulk-form'){try{const titles=parseTaskList(f.get('titles')),minutes=Number(f.get('minutes')),area=f.get('area'),priority=normalisePriority(f.get('priority'));if(!Number.isFinite(minutes)||minutes<1||minutes>240||!Object.hasOwn(AREAS,area))throw Error('Choose an area and an estimate from 1 to 240 minutes.');if(s.tasks.length+titles.length>10000)throw Error('This save has reached its 10,000-task capacity.');const createdAt=new Date().toISOString();const tasks=titles.map(title=>({id:uid(),title,area,step:title,doneMeans:title,minutes:Math.round(minutes),priority,mustDo:false,repeat:'none',weekday:dayOfWeek(day),planned:f.has('planned')?day:'',due:'',reason:'',blocked:'',blockAction:'',followUp:'',createdAt}));s.tasks.push(...tasks);closeDialog();commit();toast(`${tasks.length} tasks added. Set the most important outcomes to must-do.`);}catch(err){toast(err.message);}}
 if(form.id==='settings-form'){s.settings={...s.settings,name:f.get('name').trim()||'Marty',worldName:f.get('worldName').trim()||'The Meadow',zone:f.get('zone'),calm:f.has('calm')};commit();toast('Your preferences are saved.');}
 if(form.id==='sky-location-form'){try{const place=manualSkyLocation(f.get('latitude'),f.get('longitude'),f.get('label'));locationRequest++;locationPending=false;s.settings.skyLocation=place;commit();toast('Sky location saved.');}catch(error){toast(error.message);}}
 if(form.id==='review-form'){const r={day,feeling:f.get('feeling'),pressure:f.get('pressure'),note:f.get('note').trim()};s.reviews=s.reviews.filter(x=>x.day!==day);s.reviews.push(r);commit();toast('Review saved. Use the findings to improve tomorrow’s execution.');}
});
document.addEventListener('change',async ev=>{if(ev.target.id==='pb-area'){notebook.change(ev.target);return;}if(ev.target.id==='background-select'){chooseBackground(ev.target.value);}if(ev.target.id==='area-filter'){areaFilter=ev.target.value;render();}if(ev.target.id==='import-file'){const file=ev.target.files?.[0];if(!file)return;try{if(file.size>15000000)throw Error('Choose a backup smaller than 15 MB.');pendingImport=validateState(JSON.parse(await file.text()));pendingImport.focus=null;openDialog('Restore this backup?',`It contains ${pendingImport.tasks.length} tasks, ${pendingImport.problems.length} problems and ${pendingImport.completions.length} completed actions. It will replace the data in this browser.`, `<p class="small-text">Export your current data first if you want to keep a copy.</p><div class="dialog-actions">${btn('Export current data','export')}${btn('Cancel','close')}${btn('Replace with backup','confirm-import','','primary')}</div>`);}catch(err){pendingImport=null;toast(err.message||'That backup could not be read.');}ev.target.value='';}});
document.addEventListener('input',ev=>{if(ev.target.id==='task-search'){query=ev.target.value;const pos=ev.target.selectionStart;render();const input=document.querySelector('#task-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeDialog();}});
modal.addEventListener('close',()=>{dialogKind='';pendingImport=null;});
window.addEventListener('storage',ev=>{if(ev.key===KEY&&ev.newValue){try{clearWorldDraft();s=validateState(JSON.parse(ev.newValue));closeDialog();render();toast('Updated from another tab.');}catch{toast('A change from another tab could not be loaded.');}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){render();tick();}});
render();setInterval(tick,1000);
